1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Step = {
9	  op: string;
10	  items?: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: Step[];
16	};
17	
18	export type QuoteResult = {
19	  premium: number;
20	};
21	
22	export type ScenarioResults = {
23	  results: QuoteResult[];
24	};
25	
26	const PROCESSING_FEE = 5;
27	
28	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
38	
39	const addPercent = (amount: number, percent: number): number =>
40	  amount + (amount * percent) / 100;
41	
42	const itemBasePremium = (item: Item): number =>
43	  BASE_PREMIUM_BY_TYPE[item.type];
44	
45	const BLOCK_SIZE = 3;
46	
47	const BLOCK_PREMIUM = 60;
48	
49	const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
50	
51	const sumOfItemBasePremiums = (items: Item[]): number =>
52	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
53	
54	const policyBasePremium = (items: Item[]): number =>
55	  formsABlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);
56	
57	const roundPremiumInMHPCOsFavor = (amount: number): number =>
58	  Math.ceil(amount);
59	
60	const quotePremium = (items: Item[]): number =>
61	  roundPremiumInMHPCOsFavor(
62	    addPercent(policyBasePremium(items), FIRST_INSURANCE_SURCHARGE_PERCENT) +
63	      PROCESSING_FEE,
64	  );
65	
66	export const runScenario = (scenario: Scenario): ScenarioResults => ({
67	  results: scenario.steps.map((step) => ({
68	    premium: quotePremium(step.items ?? []),
69	  })),
70	});
